package vn.utetaste;

import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import jakarta.servlet.http.Cookie;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.*;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.security.access.AccessDeniedException;
import vn.utetaste.domain.*;
import vn.utetaste.repository.*;
import vn.utetaste.security.*;
import vn.utetaste.service.*;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;

@SpringBootTest @ActiveProfiles("test") @AutoConfigureMockMvc(print=MockMvcPrint.NONE)
class AdminPhaseTwoIntegrationTest {
    @Autowired AdminService admin;@Autowired AdminStaff staff;@Autowired TableManagement tableManagement;@Autowired Reports reports;
    @Autowired AppUserRepository users;@Autowired RestaurantTableRepository tables;@Autowired InvoiceRepository invoices;
    @Autowired CategoryRepository categories;@Autowired OrderService ops;@Autowired JwtService jwt;@Autowired MockMvc mvc;
    Actor actor(String name){return actor(users.findByUsername(name).orElseThrow());}
    Actor actor(AppUser u){return new Actor(u.getId(),u.getUsername(),u.getFullName(),u.getRole(),u.getBranch()==null?null:u.getBranch().getId(),null);}
    Cookie cookie(String name){return new Cookie("UT_ACCESS",jwt.staff(users.findByUsername(name).orElseThrow()));}
    Cookie cookie(AppUser u){return new Cookie("UT_ACCESS",jwt.staff(u));}
    Branch branch(){return admin.branch(actor("admin"),new AdminService.BranchForm(null,"Phase2-"+UUID.randomUUID(),"Địa chỉ thử","0900000000",true));}
    RestaurantTable table(Branch b){var t=new RestaurantTable();t.setBranch(b);t.setCapacity(4);t.setLabel("Test-"+UUID.randomUUID().toString().substring(0,8));return tables.saveAndFlush(t);}
    AppUser employee(Role role,Long branch){String name="p2_"+UUID.randomUUID();admin.user(actor("admin"),new AdminService.UserForm(null,name,"Nhân viên "+name,role,branch,"PhaseTwo@Test2026",true));return users.findByUsername(name).orElseThrow();}
    Dish dish(){var c=new Category();c.setName("Phase2-"+UUID.randomUUID());categories.saveAndFlush(c);return admin.dish(actor("admin"),new AdminService.DishForm(null,"Snapshot-"+UUID.randomUUID(),BigDecimal.valueOf(10000),"Món thử",c.getId(),true));}
    Actor guest(Branch b){var t=table(b);var s=ops.openTable(actor("admin"),t.getId());return new Actor(null,"guest:"+s.getId(),t.getLabel(),Role.GUEST,b.getId(),s.getId());}
    OrderService.OrderView place(Actor g,Dish d){return ops.place(g,new OrderService.PlaceRequest(UUID.randomUUID().toString(),List.of(new OrderService.Line(d.getId(),2)),""));}
    Invoice paid(Branch b,Dish d,int discount,PaymentMethod method){var g=guest(b);var o=place(g,d);for(var status:List.of(OrderStatus.CONFIRMED,OrderStatus.COOKING,OrderStatus.READY,OrderStatus.SERVED))ops.changeStatus(actor("admin"),o.id(),status);return ops.checkout(actor("admin"),g.sessionId(),discount,method);}
    LocalDate today(){return LocalDate.now(Reports.ZONE);}

    @Test void tablesFilterAndUtilizationExcludeInactiveTables(){var b=branch();var occupied=table(b);table(b);var inactive=table(b);admin.table(actor("admin"),new AdminService.TableForm(inactive.getId(),b.getId(),inactive.getLabel(),4,false));ops.openTable(actor("admin"),occupied.getId());var result=tableManagement.overview(actor("admin"),b.getId(),"all");assertThat(result.active()).isEqualTo(2);assertThat(result.occupied()).isEqualTo(1);assertThat(result.free()).isEqualTo(1);assertThat(result.inactive()).isEqualTo(1);assertThat(result.utilization()).isEqualTo(50);for(String state:List.of("occupied","free","inactive"))assertThat(tableManagement.overview(actor("admin"),b.getId(),state).rows()).hasSize(1);assertThatThrownBy(()->tableManagement.overview(actor("admin"),b.getId(),"invalid")).isInstanceOf(BusinessException.class);}
    @Test void batchPrintValidatesCountIdsAndBranchBeforeReturningAnyQr() throws Exception {var b=branch();var t=table(b);assertThat(tableManagement.printable(actor("admin"),List.of(t.getId(),t.getId()))).hasSize(1);assertThatThrownBy(()->tableManagement.printable(actor("admin"),List.of())).isInstanceOf(BusinessException.class);assertThatThrownBy(()->tableManagement.printable(actor("admin"),Collections.nCopies(51,t.getId()))).isInstanceOf(BusinessException.class);assertThatThrownBy(()->tableManagement.printable(actor("admin"),List.of(t.getId(),Long.MAX_VALUE))).isInstanceOf(BusinessException.class);assertThatThrownBy(()->tableManagement.printable(actor("waiter"),List.of(t.getId()))).isInstanceOf(AccessDeniedException.class);mvc.perform(get("/staff/tables/print").param("ids",t.getId().toString()).cookie(cookie("admin"))).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("qr-print-item")));mvc.perform(get("/staff/tables/print").param("ids",t.getId().toString()).cookie(cookie("waiter"))).andExpect(status().isForbidden());}
    @Test void qrImageDecodesAndRotationInvalidatesOldKeyWithoutOpeningTable() throws Exception {var t=table(branch());String old=t.getQrKey();byte[] bytes=mvc.perform(get("/staff/tables/"+t.getId()+"/qr.png").cookie(cookie("admin"))).andExpect(status().isOk()).andReturn().getResponse().getContentAsByteArray();var bitmap=new com.google.zxing.BinaryBitmap(new com.google.zxing.common.HybridBinarizer(new com.google.zxing.client.j2se.BufferedImageLuminanceSource(javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(bytes)))));assertThat(new com.google.zxing.MultiFormatReader().decode(bitmap).getText()).endsWith("/t/"+old);admin.rotateQr(actor("admin"),t.getId());assertThat(tables.findById(t.getId()).orElseThrow().getQrKey()).isNotEqualTo(old);assertThatThrownBy(()->ops.join(old)).isInstanceOf(BusinessException.class);var session=ops.openTable(actor("admin"),t.getId());assertThat(ops.join(tables.findById(t.getId()).orElseThrow().getQrKey()).getId()).isEqualTo(session.getId());assertThatThrownBy(()->admin.rotateQr(actor("admin"),t.getId())).isInstanceOf(BusinessException.class);assertThat(ops.join(tables.findById(t.getId()).orElseThrow().getQrKey()).getId()).isEqualTo(session.getId());}
    @Test void tableMutationsRequireRolesAndCsrf() throws Exception {var t=table(branch());mvc.perform(post("/staff/tables/"+t.getId()+"/rotate").cookie(cookie("admin"))).andExpect(status().isForbidden());mvc.perform(post("/staff/tables/"+t.getId()+"/rotate").cookie(cookie("waiter")).with(csrf())).andExpect(status().isForbidden());mvc.perform(get("/staff/tables/print").param("ids",t.getId().toString()).cookie(cookie("chef"))).andExpect(status().isForbidden());mvc.perform(post("/staff/tables/"+t.getId()+"/rotate").cookie(cookie("admin")).with(csrf())).andExpect(status().is3xxRedirection()).andExpect(flash().attributeExists("success"));}
    @Test void staffSearchFiltersAndPagingAreBounded(){var b=branch();var a=employee(Role.WAITER,b.getId());employee(Role.CHEF,b.getId());assertThat(staff.search(actor("admin"),a.getUsername(),Role.WAITER,b.getId(),"active",0,10).getContent()).extracting(AppUser::getId).containsExactly(a.getId());admin.userState(actor("admin"),a.getId(),false);assertThat(staff.search(actor("admin"),a.getUsername(),Role.WAITER,b.getId(),"inactive",0,10).getTotalElements()).isEqualTo(1);assertThat(staff.search(actor("admin"),a.getUsername(),Role.CHEF,b.getId(),"all",0,10)).isEmpty();assertThatThrownBy(()->staff.search(actor("admin"),"",Role.USER,null,"all",0,10)).isInstanceOf(BusinessException.class);assertThatThrownBy(()->staff.search(actor("admin"),"",null,null,"all",0,1000)).isInstanceOf(BusinessException.class);assertThatThrownBy(()->staff.search(actor("waiter"),"",null,null,"all",0,10)).isInstanceOf(AccessDeniedException.class);}
    @Test void staffLockUnlockAndEditRevokeJwtAndNeverExposeHash() throws Exception {var u=employee(Role.WAITER,actor("waiter").branchId());var old=cookie(u);int version=u.getTokenVersion();mvc.perform(get("/admin/users").param("edit",u.getId().toString()).cookie(cookie("admin"))).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString(u.getPasswordHash()))));admin.userState(actor("admin"),u.getId(),false);var locked=users.findById(u.getId()).orElseThrow();assertThat(locked.getTokenVersion()).isEqualTo(version+1);assertThat(locked.isActive()).isFalse();mvc.perform(get("/account/password").cookie(old)).andExpect(redirectedUrl("/login?expired"));admin.userState(actor("admin"),u.getId(),true);mvc.perform(get("/account/password").cookie(old)).andExpect(redirectedUrl("/login?expired"));var current=users.findById(u.getId()).orElseThrow();admin.user(actor("admin"),new AdminService.UserForm(current.getId(),current.getUsername(),current.getFullName(),Role.CHEF,current.getBranch().getId(),"",true));assertThat(users.findById(u.getId()).orElseThrow().getPasswordHash()).isEqualTo(u.getPasswordHash());mvc.perform(get("/staff/kitchen").cookie(cookie(current))).andExpect(redirectedUrl("/login?expired"));}
    @Test void staffMutationCannotRemoveCurrentAdminOrMutatePersonalAccounts() throws Exception {long id=actor("admin").id();assertThatThrownBy(()->admin.userState(actor("admin"),id,false)).isInstanceOf(BusinessException.class);assertThatThrownBy(()->admin.user(actor("admin"),new AdminService.UserForm(id,"admin","Admin",Role.MANAGER,actor("waiter").branchId(),"",true))).isInstanceOf(BusinessException.class);assertThat(users.countByRoleAndActiveTrue(Role.ADMIN)).isGreaterThanOrEqualTo(1);var personal=new AppUser();personal.setUsername("personal_"+UUID.randomUUID());personal.setFullName("User");personal.setRole(Role.USER);personal.setEmail("test-"+UUID.randomUUID()+"@example.test");personal.setPasswordHash("not-a-real-password-hash");users.saveAndFlush(personal);assertThatThrownBy(()->admin.userState(actor("admin"),personal.getId(),false)).isInstanceOf(BusinessException.class);assertThat(staff.search(actor("admin"),personal.getUsername(),null,null,"all",0,10)).isEmpty();for(Role role:List.of(Role.GUEST,Role.USER))assertThatThrownBy(()->admin.user(actor("admin"),new AdminService.UserForm(null,"unsafe","Unsafe",role,null,"PhaseTwo@Test2026",true))).isInstanceOf(BusinessException.class);}
    @Test void staffStateEndpointProtectsCsrfAndAdminPermission() throws Exception {var u=employee(Role.WAITER,actor("waiter").branchId());String path="/admin/users/"+u.getId()+"/state";mvc.perform(post(path).cookie(cookie("admin")).param("active","false")).andExpect(status().isForbidden());mvc.perform(post(path).cookie(cookie("manager")).with(csrf()).param("active","false")).andExpect(status().isForbidden());assertThat(users.findById(u.getId()).orElseThrow().isActive()).isTrue();mvc.perform(post(path).cookie(cookie("admin")).with(csrf()).param("active","false")).andExpect(status().is3xxRedirection()).andExpect(flash().attributeExists("success"));assertThat(users.findById(u.getId()).orElseThrow().isActive()).isFalse();}
    @Test void concurrentAdminsCannotActWithDemotedPrincipal() throws Exception {var one=employee(Role.ADMIN,null);var two=employee(Role.ADMIN,null);var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var first=pool.submit(()->{start.await();try{admin.userState(actor(one),two.getId(),false);return true;}catch(AccessDeniedException e){return false;}});var second=pool.submit(()->{start.await();try{admin.userState(actor(two),one.getId(),false);return true;}catch(AccessDeniedException e){return false;}});start.countDown();assertThat(first.get(20,TimeUnit.SECONDS)).isNotEqualTo(second.get(20,TimeUnit.SECONDS));assertThat(List.of(users.findById(one.getId()).orElseThrow(),users.findById(two.getId()).orElseThrow()).stream().filter(AppUser::isActive).count()).isEqualTo(1);}finally{pool.shutdownNow();}}
    @Test void financialReportReconcilesNetAveragePaymentsAndSnapshots(){var b=branch();var d=dish();var cash=paid(b,d,10,PaymentMethod.CASH);paid(b,d,0,PaymentMethod.BANK_TRANSFER);var unpaid=place(guest(b),d);ops.changeStatus(actor("admin"),unpaid.id(),OrderStatus.CANCELLED);place(guest(b),d);admin.dish(actor("admin"),new AdminService.DishForm(d.getId(),"Changed",BigDecimal.valueOf(999999),"Changed",d.getCategory().getId(),true));var s=reports.summary(actor("admin"),b.getId(),today(),today());assertThat(s.total()).isEqualByComparingTo("38000");assertThat(s.average()).isEqualByComparingTo("19000");assertThat(s.invoices()).hasSize(2);assertThat(s.cancelled()).isEqualTo(1);assertThat(s.served()).isEqualTo(2);assertThat(s.days().getFirst().amount()).isEqualByComparingTo(s.total());assertThat(s.payments().stream().map(Reports.PaymentTotal::amount).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo(s.total());assertThat(s.branches().getFirst().amount()).isEqualByComparingTo(s.total());assertThat(s.payments().stream().filter(p->p.method()==PaymentMethod.CASH).findFirst().orElseThrow().amount()).isEqualByComparingTo(cash.getTotal());assertThat(s.top().getFirst().name()).isEqualTo(d.getName());assertThat(s.top().getFirst().quantity()).isEqualTo(4);assertThat(s.top().getFirst().revenue()).isEqualByComparingTo("40000");}
    @Test void reportEmptyAndGlobalTotalsAreConsistent(){var b=branch();var empty=reports.summary(actor("admin"),b.getId(),today(),today());assertThat(empty.average()).isEqualByComparingTo("0");assertThat(empty.top()).isEmpty();var all=reports.summary(actor("admin"),null,today(),today());assertThat(all.branches().stream().map(Reports.BranchTotal::amount).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo(all.total());assertThat(all.payments().stream().mapToLong(Reports.PaymentTotal::count).sum()).isEqualTo(all.invoices().size());}
    @Test void reportsRespectTimezoneHalfOpenBoundsAnd366DayLimit(){var b=branch();var d=dish();var day=today();for(var time:List.of(day.atStartOfDay(Reports.ZONE).toOffsetDateTime().minusSeconds(1),day.atStartOfDay(Reports.ZONE).toOffsetDateTime(),day.plusDays(1).atStartOfDay(Reports.ZONE).toOffsetDateTime())){var i=paid(b,d,0,PaymentMethod.CASH);i.setPaidAt(time.withOffsetSameInstant(ZoneOffset.UTC));invoices.saveAndFlush(i);}assertThat(reports.summary(actor("admin"),b.getId(),day,day).invoices()).hasSize(1);assertThat(reports.summary(actor("admin"),b.getId(),day.minusDays(365),day).days()).hasSize(366);assertThatThrownBy(()->reports.summary(actor("admin"),b.getId(),day.minusDays(366),day)).isInstanceOf(BusinessException.class);assertThatThrownBy(()->reports.summary(actor("admin"),b.getId(),day.plusDays(1),day)).isInstanceOf(BusinessException.class);}
    @Test void managerReportAndCsvCannotLeakOtherBranches() throws Exception {var other=branch();assertThat(reports.scope(actor("manager"),null)).isEqualTo(actor("manager").branchId());assertThatThrownBy(()->reports.summary(actor("manager"),other.getId(),today(),today())).isInstanceOf(AccessDeniedException.class);for(String url:List.of("/staff/reports","/staff/reports/export.csv")){mvc.perform(get(url).param("branchId",other.getId().toString()).param("from",today().toString()).param("to",today().toString()).cookie(cookie("manager"))).andExpect(status().isForbidden());mvc.perform(get(url).param("from",today().toString()).param("to",today().toString()).cookie(cookie("waiter"))).andExpect(status().isForbidden());}mvc.perform(get("/staff/reports").cookie(cookie("admin"))).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("Trung bình / hóa đơn")));}
    @Test void csvExportsNetInvoicesWithUtf8BomLocalTimeAndFormulaProtection() throws Exception {var b=branch();var i=paid(b,dish(),10,PaymentMethod.CASH);var t=i.getSession().getTable();t.setLabel("  =1+1");tables.saveAndFlush(t);var result=mvc.perform(get("/staff/reports/export.csv").param("branchId",b.getId().toString()).param("from",today().toString()).param("to",today().toString()).cookie(cookie("admin"))).andExpect(status().isOk()).andExpect(header().string("Content-Disposition","attachment; filename=utetaste-revenue.csv")).andReturn().getResponse().getContentAsByteArray();String csv=new String(result,java.nio.charset.StandardCharsets.UTF_8);assertThat(csv).startsWith("\uFEFF").contains("Chi nhánh").contains("\"'  =1+1\"").contains(i.getPaidAt().atZoneSameInstant(Reports.ZONE).format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));assertThat(csv.lines()).hasSize(2);var fields=csv.lines().skip(1).findFirst().orElseThrow().split(",");assertThat(new BigDecimal(fields[4])).isEqualByComparingTo("20000");assertThat(new BigDecimal(fields[5])).isEqualByComparingTo("2000");assertThat(new BigDecimal(fields[6])).isEqualByComparingTo("18000");assertThat(fields[7]).isEqualTo("CASH");}
}
